const fs = require('fs');
const https = require('https');

// Read and parse the rotation log file
const rotationLog = fs.readFileSync('rotation-log.md', 'utf8');

// Parse the rotation log to extract credentials
function parseRotationLog(content) {
  const credentials = [];
  const lines = content.split('\n');

  let currentCredential = null;

  for (const line of lines) {
    if (line.startsWith('VARIABLE: ')) {
      if (currentCredential) {
        credentials.push(currentCredential);
      }
      currentCredential = {
        variable: line.replace('VARIABLE: ', '').trim(),
        value: '',
        status: '',
        rotation_date: '',
        notes: ''
      };
    } else if (line.startsWith('VALUE: ') && currentCredential) {
      currentCredential.value = line.replace('VALUE: ', '').trim();
    } else if (line.startsWith('STATUS: ') && currentCredential) {
      currentCredential.status = line.replace('STATUS: ', '').trim();
    } else if (line.startsWith('ROTATION_DATE: ') && currentCredential) {
      currentCredential.rotation_date = line.replace('ROTATION_DATE: ', '').trim();
    } else if (line.startsWith('NOTES: ') && currentCredential) {
      currentCredential.notes = line.replace('NOTES: ', '').trim();
    }
  }

  // Add the last credential
  if (currentCredential) {
    credentials.push(currentCredential);
  }

  return credentials;
}

// Extract metadata from the rotation log
function extractMetadata(content) {
  const metadata = {};
  const lines = content.split('\n');

  for (const line of lines) {
    if (line.includes('Rotation Date:')) {
      metadata.rotation_date = line.split('Rotation Date:')[1]?.trim() || '';
    } else if (line.includes('Rotation Initiated By:')) {
      metadata.initiated_by = line.split('Rotation Initiated By:')[1]?.trim() || '';
    } else if (line.includes('Rotation Reason:')) {
      metadata.reason = line.split('Rotation Reason:')[1]?.trim() || '';
    } else if (line.includes('Status:')) {
      metadata.status = line.split('Status:')[1]?.trim() || '';
    }
  }

  return metadata;
}

// Parse the credentials and metadata
const credentials = parseRotationLog(rotationLog);
const metadata = extractMetadata(rotationLog);

// Prepare the JSON payload
const payload = {
  credentials: credentials,
  metadata: {
    ...metadata,
    submission_timestamp: new Date().toISOString(),
    source_file: 'rotation-log.md',
    file_hash: require('crypto').createHash('sha256').update(rotationLog).digest('hex')
  }
};

console.log('Parsed credentials:');
console.log(JSON.stringify(payload, null, 2));

// Send to compliance webhook
const postData = JSON.stringify(payload);

const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/rotation-log',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData),
    'User-Agent': 'SecurityRotationBot/1.0'
  }
};

console.log('\nSending to compliance webhook...');

const req = https.request(options, (res) => {
  console.log(`Status Code: ${res.statusCode}`);
  console.log(`Status Message: ${res.statusMessage}`);

  res.on('data', (d) => {
    console.log('Response:', d.toString());
  });
});

req.on('error', (error) => {
  console.error('Error sending to webhook:', error.message);

  // Fallback: save the payload to a file for manual submission
  const fallbackFile = 'rotation-log-payload.json';
  fs.writeFileSync(fallbackFile, JSON.stringify(payload, null, 2));
  console.log(`Fallback: Payload saved to ${fallbackFile} for manual submission`);
});

req.write(postData);
req.end();

