// Secure secret management configuration
const { validationResult } = require('express-validator');

class SecretManager {
  constructor() {
    this.secrets = {};
    this.initialized = false;
  }

  // Initialize secrets from environment or external source
  async init() {
    if (this.initialized) return;

    try {
      // Load from environment (for development)
      this.loadFromEnvironment();

      // Validate all required secrets
      this.validateSecrets();

      this.initialized = true;
      console.log('Secret manager initialized successfully');
    } catch (error) {
      console.error('Failed to initialize secret manager:', error.message);
      throw error;
    }
  }

  loadFromEnvironment() {
    // Only load specific, expected environment variables
    this.secrets = {
      port: process.env.PORT || 3000,
      nodeEnv: process.env.NODE_ENV || 'development',
      allowedOrigin: process.env.ALLOWED_ORIGIN || 'http://localhost:3000',
      apiToken: process.env.API_TOKEN,

      // Optional secrets (will be validated)
      databaseUrl: process.env.DATABASE_URL,
      awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
      awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      stripeSecretKey: process.env.STRIPE_SECRET_KEY,
      anthropicApiKey: process.env.ANTHROPIC_API_KEY,
      logfireToken: process.env.LOGFIRE_TOKEN
    };
  }

  validateSecrets() {
    const errors = [];

    // Required for all environments
    if (!this.secrets.apiToken) {
      errors.push('API_TOKEN is required');
    }

    // Production-specific validations
    if (this.secrets.nodeEnv === 'production') {
      if (!this.secrets.databaseUrl) {
        errors.push('DATABASE_URL is required in production');
      }

      // Validate database URL format
      if (this.secrets.databaseUrl && !this.secrets.databaseUrl.startsWith('postgres://')) {
        errors.push('DATABASE_URL must be a valid PostgreSQL connection string');
      }
    }

    if (errors.length > 0) {
      throw new Error(`Secret validation failed: ${errors.join(', ')}`);
    }
  }

  // Get a secret with optional default
  get(key, defaultValue = null) {
    if (!this.initialized) {
      throw new Error('Secret manager not initialized');
    }

    const value = this.secrets[key];
    if (value === undefined || value === null) {
      if (defaultValue !== null) return defaultValue;
      throw new Error(`Secret '${key}' not found`);
    }

    return value;
  }

  // Check if secret exists
  has(key) {
    return this.secrets[key] !== undefined && this.secrets[key] !== null;
  }

  // Get all secrets (for testing/debugging, use cautiously)
  getAll() {
    return { ...this.secrets };
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;

