// secrets-loader.js
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManager({
      region: process.env.AWS_REGION
    });
    this.secrets = {};
  }

  async loadSecrets(secretName) {
    try {
      const data = await this.client.getSecretValue({ SecretId: secretName });
      this.secrets = JSON.parse(data.SecretString);
      return this.secrets;
    } catch (error) {
      console.error('Secrets loading failed:', error);
      throw error;
    }
  }

  get(key) {
    return this.secrets[key] || process.env[key];
  }
}

