const express = require('express');
const app = express();

// Security middleware
const { securityHeaders, corsOptions, limiter } = require('./security');
const { authenticateToken } = require('./auth');
const { sanitizeInput, validateQueryParams, handleValidationErrors } = require('./validation');

// Apply security middleware
app.use(securityHeaders);
app.use(require('cors')(corsOptions));
app.use(limiter);
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));
app.use(sanitizeInput);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.path} - IP: ${req.ip}`);
  next();
});

// Health endpoint (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected users endpoint
app.get('/users', 
  authenticateToken,
  validateQueryParams,
  handleValidationErrors,
  (req, res) => {
    // In a real application, this would query a database with proper parameterization
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply query filters if provided
    let filteredUsers = users;
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) ||
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    res.json({
      data: filteredUsers,
      count: filteredUsers.length,
      timestamp: new Date().toISOString()
    });
  }
);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't expose error details in production
  const errorResponse = process.env.NODE_ENV === 'production'
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running securely on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

