// Secure configuration management with validation and fallbacks
const Joi = require('joi');

// Environment variable schema
const envSchema = Joi.object({
  NODE_ENV: Joi.string().valid('development', 'production', 'test').default('development'),
  PORT: Joi.number().default(3000),

  // Secrets with validation
  JWT_SECRET: Joi.string().required().min(32),
  DATABASE_URL: Joi.string().uri().required(),

  // Optional secrets (can be undefined but if provided must meet criteria)
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),
  LOGFIRE_TOKEN: Joi.string().optional(),
}).unknown(true); // Allow other env vars but don't validate them

// Validate environment variables
const { error, value: envVars } = envSchema.validate(process.env, {
  abortEarly: false,
  allowUnknown: true,
});

if (error) {
  throw new Error(`Environment validation error: ${error.details.map(d => d.message).join(', ')}`);
}

// Configuration object with proper defaults and validation
const config = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,

  // Secrets (will throw if required secrets are missing)
  jwtSecret: envVars.JWT_SECRET,
  databaseUrl: envVars.DATABASE_URL,

  // Optional secrets with conditional loading
  aws: envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY ? {
    accessKeyId: envVars.AWS_ACCESS_KEY_ID,
    secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY,
  } : null,

  anthropicApiKey: envVars.ANTHROPIC_API_KEY,
  stripeSecretKey: envVars.STRIPE_SECRET_KEY,
  logfireToken: envVars.LOGFIRE_TOKEN,

  // Feature flags based on secret availability
  features: {
    hasAWS: !!envVars.AWS_ACCESS_KEY_ID && !!envVars.AWS_SECRET_ACCESS_KEY,
    hasAnthropic: !!envVars.ANTHROPIC_API_KEY,
    hasStripe: !!envVars.STRIPE_SECRET_KEY,
    hasLogfire: !!envVars.LOGFIRE_TOKEN,
  }
};

module.exports = config;

// AWS Secrets Manager integration for production environments
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class AWSSecretManager {
  constructor() {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });
    this.cache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes cache
  }

  async getSecret(secretName, useCache = true) {
    // Check cache first
    if (useCache && this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTimeout) {
        return cached.value;
      }
    }

    try {
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the result
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to fetch secret ${secretName}:`, error);
      throw new Error(`Secret retrieval failed: ${error.message}`);
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret(process.env.DATABASE_SECRET_NAME || 'production/database');
  }

  async getJWTSecret() {
    return this.getSecret(process.env.JWT_SECRET_NAME || 'production/jwt');
  }

  async getApiKeys() {
    return this.getSecret(process.env.API_KEYS_SECRET_NAME || 'production/api-keys');
  }

  clearCache() {
    this.cache.clear();
  }
}

module.exports = AWSSecretManager;

// Environment-specific secret loading strategy
const AWSSecretManager = require('./aws-secrets-manager');

class SecretLoader {
  constructor() {
    this.awsSecretsManager = null;
    this.secretsCache = new Map();
  }

  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      // Initialize AWS Secrets Manager for production
      try {
        this.awsSecretsManager = new AWSSecretManager();
        console.log('AWS Secrets Manager initialized');
      } catch (error) {
        console.warn('AWS Secrets Manager initialization failed:', error.message);
        console.warn('Falling back to environment variables');
      }
    }

    // Pre-load essential secrets
    await this.preloadSecrets();
  }

  async preloadSecrets() {
    const essentialSecrets = ['JWT_SECRET', 'DATABASE_URL'];

    for (const secretName of essentialSecrets) {
      try {
        await this.getSecret(secretName);
      } catch (error) {
        console.warn(`Failed to preload secret ${secretName}:`, error.message);
      }
    }
  }

  async getSecret(secretName, defaultValue = null) {
    // Check cache first
    if (this.secretsCache.has(secretName)) {
      return this.secretsCache.get(secretName);
    }

    let secretValue;

    // Production: Try AWS Secrets Manager first
    if (process.env.NODE_ENV === 'production' && this.awsSecretsManager) {
      try {
        const secrets = await this.awsSecretsManager.getApiKeys();
        secretValue = secrets[secretName];

        if (secretValue) {
          this.secretsCache.set(secretName, secretValue);
          return secretValue;
        }
      } catch (error) {
        console.warn(`AWS Secrets Manager failed for ${secretName}:`, error.message);
      }
    }

    // Fallback to environment variables
    if (process.env[secretName]) {
      secretValue = process.env[secretName];
      this.secretsCache.set(secretName, secretValue);
      return secretValue;
    }

    // Fallback to default value
    if (defaultValue !== null) {
      this.secretsCache.set(secretName, defaultValue);
      return defaultValue;
    }

    throw new Error(`Secret ${secretName} not found and no default provided`);
  }

  async getRequiredSecret(secretName) {
    const value = await this.getSecret(secretName);
    if (!value) {
      throw new Error(`Required secret ${secretName} is missing`);
    }
    return value;
  }

  clearCache() {
    this.secretsCache.clear();
    if (this.awsSecretsManager) {
      this.awsSecretsManager.clearCache();
    }
  }
}

// Singleton instance
const secretLoader = new SecretLoader();

// Initialize on import (async)
secretLoader.initialize().catch(error => {
  console.error('Secret loader initialization failed:', error);
});

module.exports = secretLoader;

