  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),
  LOGFIRE_TOKEN: Joi.string().optional(),
}).unknown(true);

// Validate environment variables
const { error, value: envVars } = envSchema.validate(process.env, {
  abortEarly: false,
  allowUnknown: true,
});

if (error) {
  throw new Error(`Environment validation error: ${error.details.map(d => d.message).join(', ')}`);
}

// Async configuration loading
async function loadConfig() {
  const config = {
    env: envVars.NODE_ENV,
    port: envVars.PORT,

    // Will be populated with actual secrets
    secrets: {},

    // Secret manager configuration
    secretManager: {
      databaseSecretName: envVars.DATABASE_SECRET_NAME || 'production/database',
      jwtSecretName: envVars.JWT_SECRET_NAME || 'production/jwt',
      apiKeysSecretName: envVars.API_KEYS_SECRET_NAME || 'production/api-keys',
      awsRegion: envVars.AWS_REGION,
    }
  };

  // Load secrets based on environment
  try {
    if (config.env === 'production') {
      // In production, use secret manager with fallbacks
      config.secrets.jwtSecret = await secretLoader.getRequiredSecret('JWT_SECRET');
      config.secrets.databaseUrl = await secretLoader.getRequiredSecret('DATABASE_URL');

      // Optional secrets
      config.secrets.awsAccessKeyId = await secretLoader.getSecret('AWS_ACCESS_KEY_ID');
      config.secrets.awsSecretAccessKey = await secretLoader.getSecret('AWS_SECRET_ACCESS_KEY');
      config.secrets.anthropicApiKey = await secretLoader.getSecret('ANTHROPIC_API_KEY');
      config.secrets.stripeSecretKey = await secretLoader.getSecret('STRIPE_SECRET_KEY');
      config.secrets.logfireToken = await secretLoader.getSecret('LOGFIRE_TOKEN');
    } else {
      // Development: use environment variables directly
      config.secrets.jwtSecret = envVars.JWT_SECRET || 'dev-jwt-secret-minimum-32-chars-long-here';
      config.secrets.databaseUrl = envVars.DATABASE_URL || 'postgres://localhost:5432/devdb';
      config.secrets.awsAccessKeyId = envVars.AWS_ACCESS_KEY_ID;
      config.secrets.awsSecretAccessKey = envVars.AWS_SECRET_ACCESS_KEY;
      config.secrets.anthropicApiKey = envVars.ANTHROPIC_API_KEY;
      config.secrets.stripeSecretKey = envVars.STRIPE_SECRET_KEY;
      config.secrets.logfireToken = envVars.LOGFIRE_TOKEN;
    }
  } catch (error) {
    console.error('Failed to load configuration:', error);
    throw error;
  }

  // Feature flags based on secret availability
  config.features = {
    hasAWS: !!config.secrets.awsAccessKeyId && !!config.secrets.awsSecretAccessKey,
    hasAnthropic: !!config.secrets.anthropicApiKey,
    hasStripe: !!config.secrets.stripeSecretKey,
    hasLogfire: !!config.secrets.logfireToken,
  };

  return config;
}

// Create and export async configuration
let configInstance;

async function getConfig() {
  if (!configInstance) {
    configInstance = await loadConfig();
  }
  return configInstance;
}

module.exports = { getConfig };

