// Secure secret management implementation
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  // Initialize secrets - prefer AWS Secrets Manager, fallback to env vars for local development
  async initialize() {
    try {
      // Try to use AWS Secrets Manager in production
      if (process.env.NODE_ENV === 'production' && process.env.AWS_REGION) {
        await this.loadFromAwsSecretsManager();
      } else {
        // Fallback to environment variables with validation
        await this.loadFromEnvironment();
      }
      this.initialized = true;
    } catch (error) {
      console.error('Failed to initialize secrets:', error.message);
      throw new Error('Secret initialization failed');
    }
  }

  async loadFromAwsSecretsManager() {
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION,
    });

    const secretNames = [
      'database-credentials',
      'api-keys',
      'jwt-secrets',
      'session-secrets'
    ];

    for (const secretName of secretNames) {
      try {
        const command = new GetSecretValueCommand({ SecretId: secretName });
        const response = await client.send(command);
        const secrets = JSON.parse(response.SecretString);

        for (const [key, value] of Object.entries(secrets)) {
          this.secrets.set(key, value);
        }
      } catch (error) {
        console.warn(`Failed to load secret ${secretName}:`, error.message);
      }
    }
  }

  loadFromEnvironment() {
    const requiredSecrets = [
      'DATABASE_URL',
      'SESSION_SECRET', 
      'JWT_SECRET',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    const optionalSecrets = [
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];

    // Validate required secrets
    for (const secret of requiredSecrets) {
      const value = process.env[secret];
      if (!value) {
        throw new Error(`Missing required secret: ${secret}`);
      }

      // Security validation
      if (this.isCanaryValue(value)) {
        throw new Error(`Security alert: Canary value detected for ${secret}`);
      }

      this.secrets.set(secret, value);
    }

    // Load optional secrets
    for (const secret of optionalSecrets) {
      const value = process.env[secret];
      if (value && !this.isCanaryValue(value)) {
        this.secrets.set(secret, value);
      }
    }
  }

  isCanaryValue(value) {
    // Detect canary/trap values
    const canaryPatterns = [
      /CANARY/,/canary/,/test-/,/demo-/,/example/,/placeholder/
    ];

    return canaryPatterns.some(pattern => pattern.test(value));
  }

  get(secretName) {
    if (!this.initialized) {
      throw new Error('Secret manager not initialized');
    }

    const value = this.secrets.get(secretName);
    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    return value;
  }

  getAll() {
    return Object.fromEntries(this.secrets);
  }
}

// Singleton instance
const secretManager = new SecretManager();

module.exports = secretManager;

// Secure environment variable loader with validation
const fs = require('fs');
const path = require('path');

class EnvLoader {
  constructor() {
    this.loaded = false;
  }

  load() {
    if (this.loaded) return;

    const envPath = this.getEnvFilePath();

    if (fs.existsSync(envPath)) {
      this.loadFromFile(envPath);
    } else {
      console.warn(`No .env file found at ${envPath}. Using process environment.`);
    }

    this.validateEnvironment();
    this.loaded = true;
  }

  getEnvFilePath() {
    const env = process.env.NODE_ENV || 'development';

    // Priority: .env.{NODE_ENV}.local > .env.{NODE_ENV} > .env.local > .env
    const paths = [
      `.env.${env}.local`,
      `.env.${env}`,
      '.env.local',
      '.env'
    ];

    for (const filePath of paths) {
      if (fs.existsSync(filePath)) {
        return filePath;
      }
    }

    return '.env'; // Will trigger warning if not found
  }

  loadFromFile(filePath) {
    console.log(`Loading environment from: ${filePath}`);

    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();

      // Skip comments and empty lines
      if (!trimmed || trimmed.startsWith('#')) continue;

      const [key, ...valueParts] = trimmed.split('=');
      const value = valueParts.join('=').trim();

      if (key && value) {
        // Only set if not already set in process environment
        if (!process.env[key]) {
          process.env[key] = value;
        }
      }
    }
  }

  validateEnvironment() {
    const requiredVars = {
      'NODE_ENV': ['development', 'test', 'production'],
      'PORT': value => parseInt(value) > 0 && parseInt(value) <= 65535
    };

    const sensitiveVars = [
      'SESSION_SECRET',
      'JWT_SECRET', 
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY'
    ];

    // Check required variables
    for (const [varName, validator] of Object.entries(requiredVars)) {
      const value = process.env[varName];

      if (!value) {
        throw new Error(`Missing required environment variable: ${varName}`);
      }

      if (Array.isArray(validator) && !validator.includes(value)) {
        throw new Error(`Invalid value for ${varName}: ${value}. Must be one of: ${validator.join(', ')}`);
      }

      if (typeof validator === 'function' && !validator(value)) {
        throw new Error(`Invalid value for ${varName}: ${value}`);
      }
    }

    // Check for insecure default values in sensitive variables
    for (const varName of sensitiveVars) {
      const value = process.env[varName];

      if (value && this.isInsecureDefault(value)) {
        console.warn(`⚠️  SECURITY WARNING: ${varName} appears to use a default/insecure value`);
      }
    }

    // Warn about canary values in production
    if (process.env.NODE_ENV === 'production') {
      for (const varName of sensitiveVars) {
        const value = process.env[varName];

        if (value && this.isCanaryValue(value)) {
          throw new Error(`SECURITY ALERT: Canary value detected in production for ${varName}`);
        }
      }
    }
  }

  isInsecureDefault(value) {
    const insecurePatterns = [
      /secret/,/password/,/key/,/token/,
      /default/,/test/,/demo/,/example/,
      /123/,/abc/,/admin/,/root/
    ];

    return insecurePatterns.some(pattern => 
      pattern.test(value.toLowerCase()) && value.length < 20
    );
  }

  isCanaryValue(value) {
    return /CANARY/i.test(value);
  }
}

// Create and export singleton instance
const envLoader = new EnvLoader();

module.exports = envLoader;

// Main configuration module that handles all environment and secret management
const envLoader = require('./env-loader');
const secretManager = require('./secrets');

class Config {
  constructor() {
    this.config = {};
    this.initialized = false;
  }

  async initialize() {
    if (this.initialized) return;

    try {
      // Load environment variables first
      envLoader.load();

      // Initialize secret manager
      await secretManager.initialize();

      // Build configuration object
      this.buildConfig();

      this.initialized = true;
      console.log('Configuration initialized successfully');
    } catch (error) {
      console.error('Failed to initialize configuration:', error.message);
      throw error;
    }
  }

  buildConfig() {
    this.config = {
      // Server configuration
      server: {
        port: parseInt(process.env.PORT) || 3000,
        env: process.env.NODE_ENV || 'development',
        nodeEnv: process.env.NODE_ENV || 'development'
      },

      // Database configuration
      database: {
        url: secretManager.get('DATABASE_URL'),
        pool: {
          max: parseInt(process.env.DB_POOL_MAX) || 10,
          min: parseInt(process.env.DB_POOL_MIN) || 2,
          idle: parseInt(process.env.DB_POOL_IDLE) || 30000,
          acquire: parseInt(process.env.DB_POOL_ACQUIRE) || 60000
        }
      },

