// Secure Express application with proper secret management
const express = require('express');
const cors = require('cors');
const expressRateLimit = require('express-rate-limit');
const helmet = require('helmet');
const { body, validationResult } = require('express-validator');
const config = require('./config');

// Initialize configuration before starting the app
async function initializeApp() {
  try {
    await config.initialize();

    const app = express();

    // Security middleware
    app.use(helmet({
      contentSecurityPolicy: {
        directives: {
          defaultSrc: ["'self'"],
          scriptSrc: ["'self'", "'unsafe-inline'"],
          styleSrc: ["'self'", "'unsafe-inline'"],
          imgSrc: ["'self'", "data:", "https:"],
        },
      }
    }));

    // CORS configuration using managed secrets
    app.use(cors({
      origin: config.get('app.corsOrigins', ['http://localhost:3000']),
      credentials: true,
      optionsSuccessStatus: 200
    }));

    // Rate limiting using configured values
    const limiter = expressRateLimit({
      windowMs: config.get('rateLimit.windowMs', 900000),
      max: config.get('rateLimit.max', 100),
      message: 'Too many requests from this IP, please try again later.'
    });
    app.use(limiter);

    // Body parsing with size limits
    app.use(express.json({ limit: '10kb' }));
    app.use(express.urlencoded({ extended: true, limit: '10kb' }));

    // Input validation middleware
    const validateInput = (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({
          errors: errors.array(),
          message: 'Invalid input data'
        });
      }
      next();
    };

    // Health endpoint
    app.get('/health', (req, res) => {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        uptime: process.uptime(),
        environment: config.get('server.env')
      });
    });

    // Config endpoint (secured - only show non-sensitive config in development)
    app.get('/config', (req, res) => {
      if (config.isProduction()) {
        return res.status(403).json({ error: 'Configuration access denied in production' });
      }

      // Return safe configuration info
      const safeConfig = {
        server: config.get('server'),
        app: config.get('app'),
        rateLimit: config.get('rateLimit')
      };

      res.json(safeConfig);
    });

    // Users endpoint with validation and sanitization
    app.get('/users', 
      [
        body('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
        body('name').optional().trim().isLength({ min: 1, max: 100 }).withMessage('Name must be between 1-100 characters')
      ],
      validateInput,
      (req, res) => {
        const users = [
          { 
            id: 1, 
            name: 'Alice', 
            email: 'alice@example.com',
            createdAt: '2024-01-01T00:00:00Z'
          },
          { 
            id: 2, 
            name: 'Bob', 
            email: 'bob@example.com',
            createdAt: '2024-01-02T00:00:00Z'
          },
        ];

        // Filter sensitive data before sending response
        const sanitizedUsers = users.map(user => ({
          id: user.id,
          name: user.name,
          createdAt: user.createdAt
        }));

        res.json(sanitizedUsers);
      }
    );

    // Example of a secure POST endpoint using configuration
    app.post('/users',
      [
        body('name').trim().isLength({ min: 1, max: 100 }).withMessage('Name must be between 1-100 characters'),
        body('email').isEmail().normalizeEmail().withMessage('Must be a valid email'),
        body('password').isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
      ],
      validateInput,
      (req, res) => {
        const { name, email, password } = req.body;

        // In a real application, you'd use config.get('security.bcryptRounds') here
        // to hash the password with the configured number of rounds

        res.status(201).json({
          message: 'User created successfully',
          user: { name, email } // Never return password in response
        });
      }
    );

    // Error handling middleware
    app.use((err, req, res, next) => {
      console.error('Error:', err);

      // Don't leak error details in production
      const errorResponse = config.isProduction() 
        ? { error: 'Something went wrong' }
        : { error: err.message, stack: err.stack };

      res.status(err.status || 500).json(errorResponse);
    });

    // 404 handler
    app.use((req, res) => {
      res.status(404).json({ error: 'Endpoint not found' });
    });

    const PORT = config.get('server.port', 3000);
    app.listen(PORT, () => {
      console.log(`Secure server running on port ${PORT}`);
      console.log(`Environment: ${config.get('server.env')}`);
      console.log(`App: ${config.get('app.name')} v${config.get('app.version')}`);
    });

    return app;

  } catch (error) {
    console.error('Failed to initialize application:', error.message);
    process.exit(1);
  }
}

// Export the initialization function
module.exports = initializeApp;

// If this file is run directly, initialize and start the server
if (require.main === module) {
  initializeApp().catch(error => {
    console.error('Failed to start application:', error);
    process.exit(1);
  });
}

