#!/usr/bin/env node
// Credential validation script for post-rotation verification

const crypto = require('crypto');

class CredentialValidator {
  constructor() {
    this.checks = [
      this.checkLength,
      this.checkComplexity,
      this.checkCommonPatterns,
      this.checkEntropy
    ];
  }

  validateCredential(value, name, minLength = 12) {
    console.log(`\n🔍 Validating ${name}: ${this.redactValue(value)}`);

    const results = [];
    let isValid = true;

    for (const check of this.checks) {
      const result = check.call(this, value, name, minLength);
      results.push(result);
      if (!result.valid) isValid = false;
    }

    results.forEach(result => {
      const status = result.valid ? '✅' : '❌';
      console.log(`${status} ${result.message}`);
    });

    return isValid;
  }

  checkLength(value, name, minLength) {
    const valid = value.length >= minLength;
    return {
      valid,
      message: `Length: ${value.length}/${minLength} characters` + 
               (valid ? '' : ` - Minimum ${minLength} required`)
    };
  }

  checkComplexity(value, name) {
    const hasUpper = /[A-Z]/.test(value);
    const hasLower = /[a-z]/.test(value);
    const hasNumber = /\d/.test(value);
    const hasSpecial = /[^A-Za-z0-9]/.test(value);

    const complexityScore = [hasUpper, hasLower, hasNumber, hasSpecial].filter(Boolean).length;
    const valid = complexityScore >= 3;

    return {
      valid,
      message: `Complexity: ${complexityScore}/4 character types (upper, lower, number, special)`
    };
  }

  checkCommonPatterns(value, name) {
    const forbiddenPatterns = [
      'password', 'secret', 'key', 'token', 'admin', 'root',
      'test', 'demo', 'example', '1234', 'qwerty', 'asdf'
    ];

    const foundPatterns = forbiddenPatterns.filter(pattern => 
      value.toLowerCase().includes(pattern)
    );

    const valid = foundPatterns.length === 0;

    return {
      valid,
      message: foundPatterns.length > 0 
        ? `Insecure patterns found: ${foundPatterns.join(', ')}`
        : 'No insecure patterns detected'
    };
  }

  checkEntropy(value, name) {
    // Simple entropy calculation
    const uniqueChars = new Set(value).size;
    const entropy = uniqueChars / value.length;
    const valid = entropy > 0.6; // Good entropy threshold

    return {
      valid,
      message: `Entropy: ${(entropy * 100).toFixed(1)}% (unique characters ratio)`
    };
  }

  redactValue(value) {
    if (value.length <= 8) return '********';
    return value.substring(0, 4) + '****' + value.substring(value.length - 4);
  }
}

// Example usage for the credentials we need to rotate
