// Secure secrets management module
// Use environment-specific secret providers

const fs = require('fs');
const path = require('path');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.isProduction = process.env.NODE_ENV === 'production';
  }

  // Initialize secrets based on environment
  async initialize() {
    if (this.isProduction) {
      await this.loadProductionSecrets();
    } else {
      await this.loadDevelopmentSecrets();
    }
  }

  // Load production secrets from secure sources
  async loadProductionSecrets() {
    try {
      // In production, use AWS Secrets Manager, Azure Key Vault, or similar
      // For now, fall back to environment variables with validation

      const requiredSecrets = [
        'JWT_SECRET',
        'DATABASE_URL',
        'AWS_ACCESS_KEY_ID',
        'AWS_SECRET_ACCESS_KEY'
      ];

      for (const secretName of requiredSecrets) {
        const value = process.env[secretName];
        if (!value) {
          throw new Error(`Missing required secret: ${secretName}`);
        }
        this.secrets[secretName] = value;
      }

    } catch (error) {
      console.error('Failed to load production secrets:', error.message);
      throw error;
    }
  }

  // Load development secrets with validation
  async loadDevelopmentSecrets() {
    try {
      // For development, use .env file but with validation
      const envPath = path.join(process.cwd(), '.env');

      if (fs.existsSync(envPath)) {
        require('dotenv').config();
      }

      // Validate required secrets
      const requiredSecrets = ['JWT_SECRET'];

      for (const secretName of requiredSecrets) {
        const value = process.env[secretName];
        if (!value || value.includes('your-') || value.includes('CANARY')) {
          throw new Error(`Invalid or missing development secret: ${secretName}`);
        }
        this.secrets[secretName] = value;
      }

      // Optional secrets with defaults
      this.secrets.DATABASE_URL = process.env.DATABASE_URL || 'postgres://localhost:5432/dev';
      this.secrets.PORT = process.env.PORT || 3000;

    } catch (error) {
      console.error('Failed to load development secrets:', error.message);
      throw error;
    }
  }

  // Get a secret with validation
  getSecret(name) {
    const value = this.secrets[name];
    if (!value) {
      throw new Error(`Secret not found: ${name}`);
    }
    return value;
  }

  // Check if secret exists
  hasSecret(name) {
    return !!this.secrets[name];
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

