#!/usr/bin/env node
// Secret rotation helper script

const fs = require('fs');
const crypto = require('crypto');

class SecretRotator {
  constructor() {
    this.secretsToRotate = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
      'JWT_SECRET'
    ];
  }

  // Generate a new secure secret
  generateSecret(length = 32, type = 'alphanumeric') {
    let characters;

    switch(type) {
      case 'hex':
        return crypto.randomBytes(length / 2).toString('hex');
      case 'base64':
        return crypto.randomBytes(length).toString('base64').slice(0, length);
      case 'alphanumeric':
      default:
        characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()';
        break;
    }

    let result = '';
    for (let i = 0; i < length; i++) {
      result += characters.charAt(Math.floor(Math.random() * characters.length));
    }
    return result;
  }

  // Generate AWS-like access key ID
  generateAwsAccessKeyId() {
    return 'AKIA' + this.generateSecret(16, 'alphanumeric').toUpperCase();
  }

  // Generate suggestions for each secret type
  getRotationSuggestions() {
    const suggestions = {};

    suggestions.DATABASE_URL = `postgres://newuser:${this.generateSecret(16)}@db.internal:5432/production`;
    suggestions.AWS_ACCESS_KEY_ID = this.generateAwsAccessKeyId();
    suggestions.AWS_SECRET_ACCESS_KEY = this.generateSecret(40);
    suggestions.ANTHROPIC_API_KEY = `REDACTED_ANTHROPIC_KEY${this.generateSecret(24)}`;
    suggestions.STRIPE_SECRET_KEY = `sk_live_${this.generateSecret(32)}`;
    suggestions.LOGFIRE_TOKEN = `logfire-${this.generateSecret(24)}`;
    suggestions.JWT_SECRET = this.generateSecret(64);

    return suggestions;
  }

  // Display rotation recommendations
  displayRecommendations() {
    console.log('\n=== SECRET ROTATION RECOMMENDATIONS ===\n');

    const suggestions = this.getRotationSuggestions();

    this.secretsToRotate.forEach(secret => {
      console.log(`🔐 ${secret}:`);
      console.log(`   Suggested: ${suggestions[secret]}`);
      console.log(`   Length: ${suggestions[secret].length} characters`);
      console.log('');
    });

    console.log('=== ROTATION INSTRUCTIONS ===');
    console.log('1. Generate new secrets using the suggested patterns');
    console.log('2. Update all environment configurations');
    console.log('3. Test new credentials in development');
    console.log('4. Deploy to production with overlapping validity');
    console.log('5. Revoke old credentials after confirmation');
    console.log('');
  }

  // Create a new .env file template with placeholders
  createNewEnvTemplate() {
    const template = `# NEW SECURE ENVIRONMENT CONFIGURATION
# Generated: ${new Date().toISOString()}
# Rotate all values below

# Database
DATABASE_URL=postgres://username:NEW_PASSWORD_HERE@localhost:5432/database

# AWS Credentials
AWS_ACCESS_KEY_ID=NEW_AWS_ACCESS_KEY_HERE
AWS_SECRET_ACCESS_KEY=NEW_AWS_SECRET_KEY_HERE

# API Keys
ANTHROPIC_API_KEY=NEW_ANTHROPIC_API_KEY_HERE
STRIPE_SECRET_KEY=NEW_STRIPE_SECRET_KEY_HERE

# JWT Configuration
JWT_SECRET=NEW_JWT_SECRET_HERE_MINIMUM_32_CHARS
JWT_EXPIRE=24h

# Other
LOGFIRE_TOKEN=NEW_LOGFIRE_TOKEN_HERE
PORT=3000
NODE_ENV=development
`;

    fs.writeFileSync('.env.new', template);
    console.log('✅ Created new environment template: .env.new');
    console.log('⚠️  Remember to:');
    console.log('   - Fill in actual values');
    console.log('   - Rename to .env after testing');
    console.log('   - Keep it secure and never commit to version control');
  }
}

// Run the rotator
const rotator = new SecretRotator();

if (process.argv.includes('--recommend') || process.argv.includes('-r')) {
  rotator.displayRecommendations();
}

if (process.argv.includes('--template') || process.argv.includes('-t')) {
  rotator.createNewEnvTemplate();
}

if (process.argv.length <= 2) {
  console.log('Usage:');
  console.log('  node rotate_secrets.js --recommend     # Show rotation recommendations');
  console.log('  node rotate_secrets.js --template      # Create new .env template');
  console.log('');
  rotator.displayRecommendations();
}

