/**
 * Secure Secrets Management
 * Use AWS Secrets Manager, HashiCorp Vault, or similar in production
 */

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.isProduction = process.env.NODE_ENV === 'production';
  }

  /**
   * Initialize secrets - use AWS Secrets Manager in production, .env in development
   */
  async init() {
    if (this.isProduction) {
      await this.loadFromAwsSecretsManager();
    } else {
      this.loadFromEnv();
    }
  }

  /**
   * Load secrets from AWS Secrets Manager (production)
   */
  async loadFromAwsSecretsManager() {
    try {
      const client = new SecretsManagerClient({
        region: process.env.AWS_REGION || 'us-east-1',
      });

      // Load database credentials
      const dbSecret = await client.send(new GetSecretValueCommand({
        SecretId: process.env.DB_SECRET_ARN || 'prod/database/credentials'
      }));
      this.secrets.database = JSON.parse(dbSecret.SecretString);

      // Load API keys
      const apiSecret = await client.send(new GetSecretValueCommand({
        SecretId: process.env.API_SECRET_ARN || 'prod/api/keys'
      }));
      this.secrets.apis = JSON.parse(apiSecret.SecretString);

      console.log('Secrets loaded successfully from AWS Secrets Manager');
    } catch (error) {
      console.error('Failed to load secrets from AWS:', error);
      throw new Error('Secrets initialization failed');
    }
  }

  /**
   * Load secrets from environment variables (development/test)
   */
  loadFromEnv() {
    this.secrets = {
      database: {
        url: process.env.DATABASE_URL,
        host: process.env.DB_HOST,
        port: process.env.DB_PORT,
        username: process.env.DB_USERNAME,
        password: process.env.DB_PASSWORD,
        database: process.env.DB_NAME
      },
      apis: {
        awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
        awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
        anthropicApiKey: process.env.ANTHROPIC_API_KEY,
        stripeSecretKey: process.env.STRIPE_SECRET_KEY,
        logfireToken: process.env.LOGFIRE_TOKEN
      },
      jwt: {
        secret: process.env.JWT_SECRET,
        expiresIn: process.env.JWT_EXPIRES_IN || '24h'
      }
    };

    console.log('Secrets loaded from environment variables');
  }

  /**
   * Get a secret value
   */
  get(keyPath, defaultValue = null) {
    const keys = keyPath.split('.');
    let value = this.secrets;

    for (const key of keys) {
      if (value && typeof value === 'object' && key in value) {
        value = value[key];
      } else {
        return defaultValue;
      }
    }

    return value;
  }

  /**
   * Check if secrets are properly configured
   */
  validate() {
    const requiredSecrets = [
      'database.url',
      'apis.awsAccessKeyId',
      'apis.awsSecretAccessKey',
      'jwt.secret'
    ];

    const missing = [];
    for (const secret of requiredSecrets) {
      if (!this.get(secret)) {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    return true;
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

