#!/usr/bin/env node

/**
 * Emergency security cleanup script
 * Use this to rotate credentials exposed in .env.test
 */

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

class SecurityCleanup {
  constructor() {
    this.exposedCredentials = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN'
    ];
  }

  /**
   * Generate secure random strings for credential rotation
   */
  generateSecureRandom(length = 32) {
    return crypto.randomBytes(length).toString('hex');
  }

  /**
   * Check if .env.test exists and contains sensitive data
   */
  checkExposure() {
    const envTestPath = path.join(__dirname, '..', '.env.test');

    if (!fs.existsSync(envTestPath)) {
      console.log('✅ .env.test file not found');
      return false;
    }

    const content = fs.readFileSync(envTestPath, 'utf8');
    const exposed = [];

    this.exposedCredentials.forEach(credential => {
      if (content.includes(credential)) {
        exposed.push(credential);
      }
    });

    if (exposed.length > 0) {
      console.log('🚨 CRITICAL: Sensitive credentials exposed in .env.test:');
      exposed.forEach(cred => console.log(`   - ${cred}`));
      return true;
    }

    console.log('✅ No sensitive credentials found in .env.test');
    return false;
  }

  /**
   * Securely delete .env.test file
   */
  secureDeleteEnvTest() {
    const envTestPath = path.join(__dirname, '..', '.env.test');

    if (fs.existsSync(envTestPath)) {
      try {
        // Overwrite file content before deletion (security best practice)
        const fileSize = fs.statSync(envTestPath).size;
        const randomData = crypto.randomBytes(fileSize);
        fs.writeFileSync(envTestPath, randomData);

        // Delete file
        fs.unlinkSync(envTestPath);

        console.log('✅ .env.test securely deleted');
        return true;
      } catch (error) {
        console.error('❌ Failed to delete .env.test:', error);
        return false;
      }
    }

    console.log('ℹ️  .env.test already deleted');
    return true;
  }

  /**
   * Generate security incident report
   */
  generateIncidentReport() {
    const report = {
      timestamp: new Date().toISOString(),
      incident: 'Credential exposure in version control',
      severity: 'CRITICAL',
      affected_services: [
        'Database',
        'AWS',
        'Anthropic API',
        'Stripe',
        'Logfire'
      ],
      actions_required: [
        'Rotate all exposed credentials immediately',
        'Review AWS CloudTrail logs for suspicious activity',
        'Monitor database access logs',
        'Invalidate any JWT tokens if secret was exposed',
        'Update all services with new credentials'
      ],
      new_credentials_generated: this.exposedCredentials.reduce((acc, cred) => {
        acc[cred] = `rotated_${this.generateSecureRandom(16)}`;
        return acc;
      }, {})
    };

    const reportPath = path.join(__dirname, '..', 'security-incident-report.json');
    fs.writeFileSync(reportPath, JSON.stringify(report, null, 2));

    console.log('📋 Security incident report generated:', reportPath);
    return reportPath;
  }

  /**
   * Execute full security cleanup
   */
  async executeCleanup() {
    console.log('🔒 Starting security cleanup...\n');

    // Check for exposure
    const isExposed = this.checkExposure();

    if (isExposed) {
      console.log('\n🚨 EMERGENCY: CREDENTIALS EXPOSED\n');

      // Securely delete exposed file
      this.secureDeleteEnvTest();

      // Generate incident report
      this.generateIncidentReport();

      console.log('\n✅ Security cleanup completed');
      console.log('\n🚨 IMMEDIATE ACTION REQUIRED:');
      console.log('1. Rotate ALL exposed credentials');
      console.log('2. Review access logs for all affected services');
      console.log('3. Update applications with new credentials');
      console.log('4. Consider this a security breach and act accordingly');
    } else {
      console.log('\n✅ No security exposure detected');
    }
  }
}

// Run cleanup if executed directly
if (require.main === module) {
  const cleanup = new SecurityCleanup();
  cleanup.executeCleanup().catch(console.error);
}

module.exports = SecurityCleanup;

