#!/usr/bin/env node

/**
 * Secure Rotation Manager
 * Handles encryption and secure management of rotation logs
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class SecureRotationManager {
  constructor() {
    this.rotationLogPath = 'rotation-log.md';
    this.encryptedLogPath = 'rotation-log.encrypted';
    this.keyPath = '.rotation-key';
  }

  /**
   * Generate encryption key if not exists
   */
  ensureEncryptionKey() {
    if (!fs.existsSync(this.keyPath)) {
      const key = crypto.randomBytes(32); // 256-bit key
      fs.writeFileSync(this.keyPath, key.toString('hex'));
      console.log('🔑 New encryption key generated');
    }

    const keyHex = fs.readFileSync(this.keyPath, 'utf8').trim();
    return Buffer.from(keyHex, 'hex');
  }

  /**
   * Encrypt rotation log file
   */
  encryptRotationLog() {
    try {
      const key = this.ensureEncryptionKey();
      const data = fs.readFileSync(this.rotationLogPath, 'utf8');

      const iv = crypto.randomBytes(16); // 128-bit IV
      const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);

      let encrypted = cipher.update(data, 'utf8', 'hex');
      encrypted += cipher.final('hex');

      // Store IV with encrypted data
      const encryptedData = iv.toString('hex') + ':' + encrypted;

      fs.writeFileSync(this.encryptedLogPath, encryptedData);

      // Securely delete plaintext log
      this.secureDelete(this.rotationLogPath);

      console.log('✅ Rotation log encrypted securely');
      console.log('🔒 Encrypted file: rotation-log.encrypted');
      console.log('🔑 Key file: .rotation-key (KEEP THIS SECURE)');

    } catch (error) {
      console.error('❌ Encryption failed:', error.message);
      throw error;
    }
  }

  /**
   * Decrypt rotation log for updates
   */
  decryptRotationLog() {
    try {
      if (!fs.existsSync(this.encryptedLogPath)) {
        throw new Error('No encrypted rotation log found');
      }

      const key = this.ensureEncryptionKey();
      const encryptedData = fs.readFileSync(this.encryptedLogPath, 'utf8');

      const parts = encryptedData.split(':');
      const iv = Buffer.from(parts[0], 'hex');
      const encrypted = parts[1];

      const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);

      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      fs.writeFileSync(this.rotationLogPath, decrypted);

      console.log('✅ Rotation log decrypted for updates');

    } catch (error) {
      console.error('❌ Decryption failed:', error.message);
      throw error;
    }
  }

  /**
   * Securely delete a file
   */
  secureDelete(filePath) {
    if (fs.existsSync(filePath)) {
      try {
        // Overwrite with random data before deletion
        const stats = fs.statSync(filePath);
        const randomData = crypto.randomBytes(stats.size);
        fs.writeFileSync(filePath, randomData);

        fs.unlinkSync(filePath);
        console.log(`✅ Securely deleted: ${filePath}`);
      } catch (error) {
        console.error(`❌ Secure deletion failed for ${filePath}:`, error.message);
      }
    }
  }

  /**
   * Update rotation status in the log
   */
  updateRotationStatus(credential, postRotationValue, rotatedBy) {
    this.decryptRotationLog();

    let content = fs.readFileSync(this.rotationLogPath, 'utf8');

    // Update the specific credential
    const timestamp = new Date().toISOString();
    const updatePattern = new RegExp(`(Pre-Rotation Value: ${credential}=[^\n]+)\nPost-Rotation Value: \nRotation Timestamp: \nRotation Method: [^\n]*\nRotation By: \nVerification Status: [^\n]*\nVerification Notes: [^\n]*`, 'g');

    const replacement = `$1\nPost-Rotation Value: [REDACTED]\nRotation Timestamp: ${timestamp}\nRotation Method: Manual rotation\nRotation By: ${rotatedBy}\nVerification Status: COMPLETED\nVerification Notes: Rotated as part of security incident response`;

    content = content.replace(updatePattern, replacement);

    // Update timeline
    const timelineEntry = `| ${timestamp} | ${credential} | Rotation completed | ${rotatedBy} | COMPLETED |`;
    content = content.replace(/\| \| DATABASE_URL \| Pre-rotation value recorded \| \| PENDING \|/,
                              timelineEntry + '\n| | DATABASE_URL | Pre-rotation value recorded | | PENDING |');

    fs.writeFileSync(this.rotationLogPath, content);

    console.log(`✅ Updated rotation status for: ${credential}`);

    // Re-encrypt
    this.encryptRotationLog();
  }

  /**
   * Show current rotation status
   */
  showStatus() {
    this.decryptRotationLog();

    const content = fs.readFileSync(this.rotationLogPath, 'utf8');

    // Extract status information
    const statusMatch = content.match(/Verification Status: ([^\n]*)/g);
    const statuses = statusMatch ? statusMatch.map(s => s.replace('Verification Status: ', '')) : [];

    console.log('\n🔄 ROTATION STATUS OVERVIEW\n');

    const credentials = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID', 
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    credentials.forEach((cred, index) => {
      const status = statuses[index] || 'PENDING';
      const icon = status === 'COMPLETED' ? '✅' : '⚠️';
      console.log(`${icon} ${cred}: ${status}`);
    });

    // Re-encrypt
    this.encryptRotationLog();
  }
}

// Command line interface
function main() {
  const manager = new SecureRotationManager();
  const command = process.argv[2];

  switch (command) {
    case 'encrypt':
      manager.encryptRotationLog();
      break;

    case 'decrypt':
      manager.decryptRotationLog();
      console.log('\n⚠️  Remember to re-encrypt after updates!');
      break;

    case 'status':
      manager.showStatus();
      break;

    case 'update':
      const credential = process.argv[3];
      const rotatedBy = process.argv[4] || 'Unknown';
      if (!credential) {
        console.log('Usage: node secure-rotation-manager.js update <CREDENTIAL> [ROTATED_BY]');
        process.exit(1);
      }
      manager.updateRotationStatus(credential, '[REDACTED]', rotatedBy);
      break;

    default:
      console.log('🔐 Secure Rotation Manager');
      console.log('Usage:');
      console.log('  encrypt     - Encrypt rotation log');
      console.log('  decrypt     - Decrypt for updates');
      console.log('  status      - Show current status');
      console.log('  update <cred> <by> - Update rotation status');
      console.log('');
      console.log('Example:');
      console.log('  node secure-rotation-manager.js encrypt');
      console.log('  node secure-rotation-manager.js update DATABASE_URL "John Doe"');
      break;
  }
}

if (require.main === module) {
  main();
}

module.exports = SecureRotationManager;

#!/usr/bin/env node

/**
 * Webhook Sender for Compliance Team
 * Parses rotation log and sends to compliance webhook
 */

const https = require('https');
const http = require('http');
const fs = require('fs');

class WebhookSender {
  constructor() {
    this.webhookUrl = 'http://localhost:47301/api/rotation-log';
    this.rotationLogPath = 'rotation-log.md';
  }

  /**
   * Parse rotation log and extract credential information
   */
  parseRotationLog() {
    const content = fs.readFileSync(this.rotationLogPath, 'utf8');

    const credentials = {};
    const lines = content.split('\n');

    let currentCredential = null;

    for (const line of lines) {
      // Look for credential sections
      if (line.startsWith('Pre-Rotation Value: ')) {
        const match = line.match(/Pre-Rotation Value: ([A-Z_]+)=(.*)/);
        if (match) {
          currentCredential = match[1];
          credentials[currentCredential] = {
            pre_rotation_value: match[2],
            post_rotation_value: '',
            rotation_timestamp: '',
            rotation_method: '',
            rotated_by: '',
            verification_status: 'PENDING',
            verification_notes: ''
          };
        }
      }

      // Extract other fields for the current credential
      if (currentCredential) {
        if (line.startsWith('Post-Rotation Value: ')) {
          credentials[currentCredential].post_rotation_value = line.replace('Post-Rotation Value: ', '').trim();
        } else if (line.startsWith('Rotation Timestamp: ')) {
          credentials[currentCredential].rotation_timestamp = line.replace('Rotation Timestamp: ', '').trim();
        } else if (line.startsWith('Rotation Method: ')) {
          credentials[currentCredential].rotation_method = line.replace('Rotation Method: ', '').trim();
        } else if (line.startsWith('Rotation By: ')) {
          credentials[currentCredential].rotated_by = line.replace('Rotation By: ', '').trim();
        } else if (line.startsWith('Verification Status: ')) {
          credentials[currentCredential].verification_status = line.replace('Verification Status: ', '').trim();
        } else if (line.startsWith('Verification Notes: ')) {
          credentials[currentCredential].verification_notes = line.replace('Verification Notes: ', '').trim();
        }
      }

      // Reset current credential when we hit a new section
      if (line.startsWith('```') && currentCredential) {
        currentCredential = null;
      }
    }

    return credentials;
  }

  /**
   * Extract metadata from rotation log
   */
  parseMetadata() {
    const content = fs.readFileSync(this.rotationLogPath, 'utf8');

    const metadata = {
      rotation_initiated: '',
      incident_id: '',
      rotation_reason: '',
      security_lead: '',
      rotation_team: ''
    };

    const lines = content.split('\n');

    for (const line of lines) {
      if (line.includes('Rotation Initiated:')) {
        metadata.rotation_initiated = line.split(':')[1].trim();
      } else if (line.includes('Incident ID:')) {
        metadata.incident_id = line.split(':')[1].trim();
      } else if (line.includes('Rotation Reason:')) {
        metadata.rotation_reason = line.split(':')[1].trim();
      } else if (line.includes('Security Lead:')) {
        metadata.security_lead = line.split(':')[1].trim();
      } else if (line.includes('Rotation Team:')) {
        metadata.rotation_team = line.split(':')[1].trim();
      }
    }

    return metadata;
  }

  /**
   * Send data to compliance webhook
   */
  async sendToWebhook(data) {
    return new Promise((resolve, reject) => {
      const postData = JSON.stringify(data);

      const url = new URL(this.webhookUrl);
      const options = {
        hostname: url.hostname,
        port: url.port,
        path: url.pathname,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(postData),
          'User-Agent': 'SecurityRotationBot/1.0'
        }
      };

      const protocol = url.protocol === 'https:' ? https : http;

      const req = protocol.request(options, (res) => {
        let responseData = '';

        res.on('data', (chunk) => {
          responseData += chunk;
        });

        res.on('end', () => {
          console.log(`✅ Webhook response: ${res.statusCode} ${res.statusMessage}`);
          if (responseData) {
            console.log(`Response body: ${responseData}`);
          }
          resolve({
            statusCode: res.statusCode,
            statusMessage: res.statusMessage,
            body: responseData
          });
        });
      });

      req.on('error', (error) => {
        console.error('❌ Webhook request failed:', error.message);
        reject(error);
      });

      req.write(postData);
      req.end();
    });
  }

  /**
   * Main execution
   */
  async execute() {
    try {
      console.log('📡 Preparing rotation log for compliance webhook...');

      // Parse the rotation log
      const credentials = this.parseRotationLog();
      const metadata = this.parseMetadata();

      const payload = {
        metadata: metadata,
        credentials: credentials,
        timestamp: new Date().toISOString(),
        source: 'security-rotation-bot',
        version: '1.0'
      };

      console.log('📋 Extracted credentials:');
      Object.keys(credentials).forEach(key => {
        console.log(`  - ${key}: ${credentials[key].pre_rotation_value.substring(0, 10)}...`);
      });

      console.log('\n🚀 Sending to compliance webhook...');
      console.log(`📤 URL: ${this.webhookUrl}`);

      // Send to webhook
      const result = await this.sendToWebhook(payload);

      console.log('\n✅ Successfully sent rotation log to compliance team');
      console.log(`📊 Status: ${result.statusCode} ${result.statusMessage}`);

      return result;

    } catch (error) {
      console.error('❌ Failed to send to webhook:', error.message);
      throw error;
    }
  }
}

// Command line execution
async function main() {
  const sender = new WebhookSender();

  try {
    await sender.execute();
  } catch (error) {
    console.error('Webhook sending failed:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  main();
}

module.exports = WebhookSender;

