const path = require('path');

class SecretRotator {
  constructor() {
    this.secretsToRotate = [
      {
        name: 'DATABASE_URL',
        description: 'Database connection string',
        rotationGuide: 'Change database user password and update connection string',
        validation: (value) => value.includes('postgres://') || value.includes('mysql://')
      },
