#!/usr/bin/env node

// Secure credential rotation utility
// This script helps track rotation status and validate new credentials

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

class SecureRotator {
  constructor() {
    this.rotationId = `ROT-${Date.now()}-TEST`;
    this.preRotationValues = {};
    this.postRotationValues = {};
    this.rotationStatus = {};

    this.loadPreRotationValues();
  }

  loadPreRotationValues() {
    try {
      const envContent = fs.readFileSync('.env.test', 'utf8');
      const lines = envContent.split('\n');

      lines.forEach(line => {
        if (line.trim() && !line.startsWith('#')) {
          const [key, value] = line.split('=').map(s => s.trim());
          if (key && value) {
            this.preRotationValues[key] = value;
            this.rotationStatus[key] = 'PENDING';
          }
        }
      });

      console.log(`✅ Loaded ${Object.keys(this.preRotationValues).length} pre-rotation values`);
    } catch (error) {
      console.log('⚠️  No .env.test file found, proceeding with manual rotation');
    }
  }

  hashValue(value) {
    return crypto.createHash('sha256').update(value).digest('hex');
  }

  validateRotation(oldValue, newValue) {
    if (oldValue === newValue) {
      return { valid: false, reason: 'New value cannot be the same as old value' };
    }

    if (newValue.length < 8) {
      return { valid: false, reason: 'New value is too short' };
    }

    // Additional validation rules based on credential type
    if (oldValue.includes('AKIA') && !newValue.startsWith('AKIA')) {
      return { valid: false, reason: 'AWS access key must start with AKIA' };
    }

    if (oldValue.includes('sk_live') && !newValue.startsWith('sk_live')) {
      return { valid: false, reason: 'Stripe key must start with sk_live' };
    }

    return { valid: true, reason: 'Validation passed' };
  }

  markAsRotated(credentialName, newValue, rotatedBy) {
    if (!this.preRotationValues[credentialName]) {
      console.log(`❌ Unknown credential: ${credentialName}`);
      return false;
    }

    const validation = this.validateRotation(this.preRotationValues[credentialName], newValue);
    if (!validation.valid) {
      console.log(`❌ Rotation validation failed: ${validation.reason}`);
      return false;
    }

    this.postRotationValues[credentialName] = newValue;
    this.rotationStatus[credentialName] = {
      status: 'COMPLETED',
      rotatedAt: new Date().toISOString(),
      rotatedBy: rotatedBy || 'unknown',
      oldValueHash: this.hashValue(this.preRotationValues[credentialName]),
      newValueHash: this.hashValue(newValue)
    };

    console.log(`✅ ${credentialName} rotation marked as completed`);
    return true;
  }

  generateRotationReport() {
    const report = {
      rotationId: this.rotationId,
      timestamp: new Date().toISOString(),
      credentials: {}
    };

    for (const [key, oldValue] of Object.entries(this.preRotationValues)) {
      report.credentials[key] = {
        preRotation: {
          value: oldValue,
          hash: this.hashValue(oldValue)
        },
        postRotation: this.rotationStatus[key]?.status === 'COMPLETED' ? {
          value: 'REDACTED', // Never store post-rotation values in logs
          hash: this.rotationStatus[key].newValueHash,
          rotatedAt: this.rotationStatus[key].rotatedAt,
          rotatedBy: this.rotationStatus[key].rotatedBy
        } : {
          status: 'PENDING'
        },
        status: this.rotationStatus[key]?.status || 'PENDING'
      };
    }

    return JSON.stringify(report, null, 2);
  }

  getRotationStatus() {
    const completed = Object.values(this.rotationStatus).filter(s => s.status === 'COMPLETED').length;
    const total = Object.keys(this.rotationStatus).length;

    return {
      completed,
      total,
      percentage: total > 0 ? Math.round((completed / total) * 100) : 0
    };
  }
}

// Command line interface
if (require.main === module) {
  const rotator = new SecureRotator();

  const command = process.argv[2];

  switch (command) {
    case 'status':
      const status = rotator.getRotationStatus();
      console.log(`\n🔄 Rotation Status: ${status.completed}/${status.total} completed (${status.percentage}%)`);

      for (const [cred, info] of Object.entries(rotator.rotationStatus)) {
        const statusIcon = info.status === 'COMPLETED' ? '✅' : '⏳';
        console.log(`${statusIcon} ${cred}: ${info.status}`);
        if (info.status === 'COMPLETED') {
          console.log(`   Rotated at: ${info.rotatedAt}`);
          console.log(`   Old hash: ${info.oldValueHash.substring(0, 16)}...`);
          console.log(`   New hash: ${info.newValueHash.substring(0, 16)}...`);
        }
      }
      break;

    case 'report':
      const report = rotator.generateRotationReport();
      fs.writeFileSync(`rotation-report-${Date.now()}.json`, report);
      console.log('📊 Rotation report generated');
      break;

    case 'rotate':
      const credName = process.argv[3];
      const newValue = process.argv[4];
      const rotatedBy = process.argv[5] || 'cli';

      if (!credName || !newValue) {
        console.log('Usage: node secure-rotation.js rotate <CREDENTIAL_NAME> <NEW_VALUE> [rotated_by]');
        process.exit(1);
      }

      const success = rotator.markAsRotated(credName, newValue, rotatedBy);
      if (success) {
        console.log(`✅ ${credName} rotation recorded`);
      }
      break;

    default:
      console.log('Secure Credential Rotation Utility');
      console.log('===================================');
      console.log('Usage:');
      console.log('  node secure-rotation.js status          - Show rotation status');
      console.log('  node secure-rotation.js report          - Generate rotation report');
      console.log('  node secure-rotation.js rotate <key> <value> [by] - Record rotation');
      console.log('');
      console.log('Example:');
      console.log('  node secure-rotation.js rotate AWS_ACCESS_KEY_ID REDACTED_AWS_AKID alice');
  }
}

module.exports = SecureRotator;

#!/usr/bin/env node

// Script to POST rotation log contents to compliance webhook

const fs = require('fs');
const https = require('https');

function parseRotationLog(content) {
  const lines = content.split('\n');
  const credentials = {};

  let currentSection = '';

  for (const line of lines) {
    if (line.startsWith('### ')) {
      currentSection = line.replace('### ', '').trim();
    } else if (line.startsWith('```') && currentSection) {
      // Skip code block markers
      continue;
    } else if (currentSection && line.trim() && !line.startsWith('#') && !line.startsWith('```')) {
      const [key, value] = line.split('=').map(s => s.trim());
      if (key && value) {
        credentials[key] = value;
      }
    }
  }

  return credentials;
}

function postToWebhook(credentials) {
  const postData = JSON.stringify({
    credentials: credentials,
    metadata: {
      timestamp: new Date().toISOString(),
      rotation_id: `ROT-${Date.now()}-TEST`,
      environment: 'Test/Development',
      reason: 'Potential exposure via .env.test file'
    }
  });

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/rotation-log',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData),
      'User-Agent': 'Compliance-Webhook-Client/1.0'
    }
  };

  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          headers: res.headers,
          body: responseData
        });
      });
    });

    req.on('error', (error) => {
      reject(error);
    });

    req.write(postData);
    req.end();
  });
}

async function main() {
  try {
    // Read the rotation log file
    const logContent = fs.readFileSync('rotation-log.md', 'utf8');

    // Parse the credentials from the log
    const credentials = parseRotationLog(logContent);

    console.log('📋 Extracted credentials from rotation log:');
    Object.keys(credentials).forEach(key => {
      console.log(`   ${key}: ${credentials[key]}`);
    });

    // POST to compliance webhook
    console.log('\n🌐 POSTing to compliance webhook: http://localhost:47301/api/rotation-log');

    const response = await postToWebhook(credentials);

    console.log('✅ Webhook response:');
    console.log(`   Status Code: ${response.statusCode}`);
    console.log(`   Response: ${response.body}`);

    if (response.statusCode >= 200 && response.statusCode < 300) {
      console.log('\n🎉 Successfully submitted rotation log to compliance webhook');
    } else {
      console.log('\n❌ Failed to submit rotation log');
      process.exit(1);
    }

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Run if called directly
if (require.main === module) {
  main();
}

module.exports = { parseRotationLog, postToWebhook };

