// Security audit script
const fs = require('fs');
const path = require('path');

class SecurityAudit {
  static checkDependencies() {
    console.log('🔍 Checking dependencies for known vulnerabilities...');

    const packageJson = JSON.parse(fs.readFileSync('package.json', 'utf8'));
    const dependencies = {...packageJson.dependencies, ...packageJson.devDependencies};

    console.log('📦 Dependencies found:', Object.keys(dependencies));

    // Check for known vulnerable packages (this would be expanded in real usage)
    const vulnerablePackages = {
      'express': '4.18.2', // Example - check actual versions
      'helmet': '7.1.0'
    };

    let vulnerabilities = 0;
    for (const [pkg, version] of Object.entries(vulnerablePackages)) {
      if (dependencies[pkg] && dependencies[pkg] !== version) {
        console.warn(`   ⚠️  ${pkg}: Version ${dependencies[pkg]} may have vulnerabilities`);
        vulnerabilities++;
      }
    }

    return vulnerabilities;
  }

  static checkEnvironment() {
    console.log('🔍 Checking environment configuration...');

    let issues = 0;

    // Check if .env files exist that shouldn't be committed
    const sensitiveFiles = ['.env', '.env.local', '.env.test'];
    sensitiveFiles.forEach(file => {
      if (fs.existsSync(file)) {
        console.warn(`   ⚠️  ${file}: Should not be committed to version control`);
        issues++;
      }
    });

    // Check if .gitignore contains sensitive patterns
    if (fs.existsSync('.gitignore')) {
      const gitignore = fs.readFileSync('.gitignore', 'utf8');
      const requiredPatterns = ['.env', 'node_modules', 'npm-debug.log'];

      requiredPatterns.forEach(pattern => {
        if (!gitignore.includes(pattern)) {
          console.warn(`   ⚠️  .gitignore: Missing pattern '${pattern}'`);
          issues++;
        }
      });
    } else {
      console.warn('   ❌ .gitignore: File missing');
      issues++;
    }

    return issues;
  }

  static checkFiles() {
    console.log('🔍 Checking file permissions and structure...');

    let issues = 0;

    // Check if config directory exists
    if (!fs.existsSync('config')) {
      console.warn('   ⚠️  config/: Directory missing for security configuration');
      issues++;
    }

    // Check if utils directory exists
    if (!fs.existsSync('utils')) {
      console.warn('   ⚠️  utils/: Directory missing for validation utilities');
      issues++;
    }

    return issues;
  }

  static run() {
    console.log('\n🛡️  SECURITY AUDIT REPORT\n');

    const depIssues = this.checkDependencies();
    const envIssues = this.checkEnvironment();
    const fileIssues = this.checkFiles();

    const totalIssues = depIssues + envIssues + fileIssues;

    console.log('\n📊 SUMMARY:');
    console.log(`   Dependency issues: ${depIssues}`);
    console.log(`   Environment issues: ${envIssues}`);
    console.log(`   File structure issues: ${fileIssues}`);
    console.log(`   Total issues found: ${totalIssues}`);

    if (totalIssues === 0) {
      console.log('✅ No critical security issues found!');
    } else {
      console.log('❌ Security issues found. Please review warnings above.');
    }

    return totalIssues;
  }
}

// Run audit if called directly
if (require.main === module) {
  SecurityAudit.run();
}

module.exports = SecurityAudit;

