// Secure secret management configuration
// Supports multiple backends: AWS Secrets Manager, Azure Key Vault, or local .env for development

const crypto = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.backend = process.env.SECRETS_BACKEND || 'local';
    this.initialized = false;
  }

  async init() {
    if (this.initialized) return;

    try {
      switch (this.backend) {
        case 'aws':
          await this.loadFromAWS();
          break;
        case 'azure':
          await this.loadFromAzure();
          break;
        case 'local':
        default:
          await this.loadFromLocal();
          break;
      }
      this.initialized = true;
      console.log(`✅ Secrets loaded from ${this.backend} backend`);
    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);
      throw error;
    }
  }

  async loadFromAWS() {
    // AWS Secrets Manager integration
    // This would use the AWS SDK in production
    console.log('🔐 Loading secrets from AWS Secrets Manager...');

    // For now, fall back to environment variables
    // In real implementation, this would use AWS SDK
    await this.loadFromLocal();
  }

  async loadFromAzure() {
    // Azure Key Vault integration
    console.log('🔐 Loading secrets from Azure Key Vault...');

    // Fall back to environment variables for now
    await this.loadFromLocal();
  }

  async loadFromLocal() {
    console.log('🔐 Loading secrets from environment variables...');

    // Load from process.env but validate and sanitize
    const secretsToLoad = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY',
      'STRIPE_SECRET_KEY',
      'LOGFIRE_TOKEN',
      'SESSION_SECRET',
      'JWT_SECRET',
      'ENCRYPTION_KEY'
    ];

    secretsToLoad.forEach(key => {
      const value = process.env[key];
      if (value) {
        this.secrets.set(key, value);

        // Security validation
        if (this.isTestOrCanaryValue(value)) {
          console.warn(`⚠️  SECURITY WARNING: ${key} contains test/canary value`);
        }
      }
    });
  }

  isTestOrCanaryValue(value) {
    const testPatterns = [
      'CANARY',
      'test',
      'example',
      'your_',
      'placeholder',
      'demo',
      'mock'
    ];

    return testPatterns.some(pattern => 
      value && typeof value === 'string' && value.includes(pattern)
    );
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized. Call init() first.');
    }

    const value = this.secrets.get(key);
    if (!value) {
      throw new Error(`Secret not found: ${key}`);
    }

    return value;
  }

  getOptional(key, defaultValue = null) {
    try {
      return this.get(key);
    } catch {
      return defaultValue;
    }
  }

  // Encryption utilities for sensitive data
  encrypt(data) {
    const algorithm = 'aes-256-gcm';
    const key = crypto.scryptSync(this.get('ENCRYPTION_KEY') || 'fallback-key-but-change-this', 'salt', 32);
    const iv = crypto.randomBytes(16);

    const cipher = crypto.createCipheriv(algorithm, key, iv);
    let encrypted = cipher.update(data, 'utf8', 'hex');
    encrypted += cipher.final('hex');

    const authTag = cipher.getAuthTag();

    return {
      iv: iv.toString('hex'),
      authTag: authTag.toString('hex'),
      content: encrypted
    };
  }

  decrypt(encryptedData) {
    const algorithm = 'aes-256-gcm';
    const key = crypto.scryptSync(this.get('ENCRYPTION_KEY') || 'fallback-key-but-change-this', 'salt', 32);

    const decipher = crypto.createDecipheriv(
      algorithm, 
      key, 
      Buffer.from(encryptedData.iv, 'hex')
    );

    decipher.setAuthTag(Buffer.from(encryptedData.authTag, 'hex'));

    let decrypted = decipher.update(encryptedData.content, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    return decrypted;
  }

  // Rotate secrets (would integrate with cloud provider APIs)
  async rotateSecret(key, newValue) {
    console.log(`🔄 Rotating secret: ${key}`);
    this.secrets.set(key, newValue);

    // In production, this would update the cloud secrets manager
    // and invalidate old credentials
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

// Utility to load and validate secrets on application startup
const secretsManager = require('../config/secrets');

class SecretsLoader {
  static async loadSecrets() {
    try {
      await secretsManager.init();

      // Validate critical secrets
      this.validateCriticalSecrets();

      console.log('✅ All secrets loaded and validated successfully');
      return true;

    } catch (error) {
      console.error('❌ Failed to load secrets:', error.message);

      // In production, we might want to exit if secrets can't be loaded
      if (process.env.NODE_ENV === 'production') {
        console.error('💀 CRITICAL: Cannot start without valid secrets in production');
        process.exit(1);
      }

      return false;
    }
  }

  static validateCriticalSecrets() {
    const criticalSecrets = [
      'DATABASE_URL',
      'SESSION_SECRET',
      'JWT_SECRET'
    ];

    criticalSecrets.forEach(secret => {
      try {
        const value = secretsManager.get(secret);

        // Additional validation based on secret type
        switch (secret) {
          case 'SESSION_SECRET':
          case 'JWT_SECRET':
            if (value.length < 32) {
              console.warn(`⚠️  ${secret}: Should be at least 32 characters for security`);
            }
            break;

          case 'DATABASE_URL':
            if (!value.includes('://')) {
              throw new Error('Invalid database URL format');
            }
            break;
        }

      } catch (error) {
        if (process.env.NODE_ENV === 'production') {
          throw new Error(`Missing critical secret: ${secret}`);
        } else {
          console.warn(`⚠️  Missing optional secret: ${secret}`);
        }
      }
    });
  }

  static getSecret(key, defaultValue = null) {
    try {
      return secretsManager.get(key);
    } catch (error) {
      if (defaultValue !== null) {
        return defaultValue;
      }
      throw error;
    }
  }

  static getAllSecrets() {
    // Returns a safe representation (masks sensitive values)
    const secrets = {};

    // This would be the actual secret keys from your configuration
    const secretKeys = [
      'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY',
      'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN',
      'SESSION_SECRET', 'JWT_SECRET'
    ];

    secretKeys.forEach(key => {
      try {
        const value = secretsManager.get(key);
        secrets[key] = this.maskSecret(value);
      } catch {
        secrets[key] = 'NOT_SET';
      }
    });

    return secrets;
  }

  static maskSecret(value, visibleChars = 4) {
    if (!value || typeof value !== 'string') return '********';

    if (value.length <= visibleChars * 2) {
      return '*'.repeat(value.length);
    }

    const firstPart = value.substring(0, visibleChars);
    const lastPart = value.substring(value.length - visibleChars);

    return `${firstPart}${'*'.repeat(value.length - visibleChars * 2)}${lastPart}`;
  }
}

module.exports = SecretsLoader;

