// Script to generate redacted secret values for rotation tracking
const fs = require('fs');
const path = require('path');

function redactValue(value, visibleChars = 4) {
  if (!value || typeof value !== 'string') return '********';

  if (value.length <= visibleChars * 2) {
    return '*'.repeat(value.length);
  }

  const firstPart = value.substring(0, visibleChars);
  const lastPart = value.substring(value.length - visibleChars);

  return `${firstPart}${'*'.repeat(value.length - visibleChars * 2)}${lastPart}`;
}

function parseEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const secrets = {};

    lines.forEach(line => {
      // Skip comments and empty lines
      if (!line.trim() || line.trim().startsWith('#')) return;

      const equalsIndex = line.indexOf('=');
      if (equalsIndex > 0) {
        const key = line.substring(0, equalsIndex).trim();
        const value = line.substring(equalsIndex + 1).trim();

        // Only include actual secret values (not NODE_ENV, PORT, etc.)
        if (key && value && !['NODE_ENV', 'PORT'].includes(key)) {
          secrets[key] = value;
        }
      }
    });

    return secrets;
  } catch (error) {
    console.warn(`⚠️  Could not read ${filePath}:`, error.message);
    return {};
  }
}

function generateReport() {
  console.log('🔍 Generating Redacted Secret Report\n');

  const envFiles = [
    { name: '.env.test', path: '.env.test' },
    { name: '.env.development', path: '.env.development' }
  ];

  let allSecrets = [];

  envFiles.forEach(envFile => {
    console.log(`📁 ${envFile.name}:`);
    console.log('─'.repeat(50));

    const secrets = parseEnvFile(envFile.path);

    if (Object.keys(secrets).length === 0) {
      console.log('   No secrets found\n');
      return;
    }

    Object.entries(secrets).forEach(([key, value]) => {
      const redacted = redactValue(value);
      const isCanary = value.includes('CANARY');
      const status = isCanary ? '🚨 CANARY' : '⚠️  ACTIVE';

      console.log(`   ${key.padEnd(25)}: ${redacted.padEnd(20)} (${value.length} chars) ${status}`);

      allSecrets.push({
        file: envFile.name,
        variable: key,
        redacted: redacted,
        length: value.length,
        isCanary: isCanary,
        status: isCanary ? 'CRITICAL' : 'ACTIVE'
      });
    });

    console.log('');
  });

  // Generate CSV output for spreadsheet
  console.log('📊 CSV Format for Spreadsheet:');
  console.log('File,Variable,Redacted Value,Length,Status,Priority');

  allSecrets.forEach(secret => {
    const priority = secret.isCanary ? 'URGENT' : 'MEDIUM';
    console.log(`"${secret.file}","${secret.variable}","${secret.redacted}",${secret.length},"${secret.status}","${priority}"`);
  });

  // Summary
  const criticalCount = allSecrets.filter(s => s.isCanary).length;
  const totalCount = allSecrets.length;

  console.log('\n📈 Summary:');
  console.log(`   Total secrets: ${totalCount}`);
  console.log(`   Critical (CANARY): ${criticalCount}`);
  console.log(`   Active: ${totalCount - criticalCount}`);
  console.log(`   Rotation urgency: ${criticalCount > 0 ? '🚨 IMMEDIATE' : '⚠️  SCHEDULED'}`);
}

// Run the report
generateReport();

// Script to POST rotation log to compliance webhook
const fs = require('fs');
const https = require('https');

// Read the rotation log file
const rotationLogContent = fs.readFileSync('rotation-log.md', 'utf8');

// Create the JSON payload with the 'credentials' field
const payload = JSON.stringify({
  credentials: rotationLogContent
});

// Webhook configuration
const webhookUrl = new URL('http://localhost:47301/api/rotation-log');
const options = {
  hostname: webhookUrl.hostname,
  port: webhookUrl.port,
  path: webhookUrl.pathname,
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload),
    'User-Agent': 'SecurityRotationBot/1.0'
  }
};

console.log('📤 POSTing rotation log to compliance webhook...');
console.log(`🔗 URL: ${webhookUrl.toString()}`);
console.log(`📄 Content length: ${rotationLogContent.length} characters`);

// Make the POST request
const req = https.request(options, (res) => {
  console.log(`📨 Response status: ${res.statusCode}`);
  console.log(`📋 Response headers: ${JSON.stringify(res.headers, null, 2)}`);

  let responseData = '';

  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log('✅ POST completed');
    console.log('📥 Response body:', responseData);

    if (res.statusCode >= 200 && res.statusCode < 300) {
      console.log('🎉 Rotation log successfully submitted to compliance webhook!');
    } else {
      console.log('❌ Webhook returned error status');
    }
  });
});

req.on('error', (error) => {
  console.error('💥 Error making POST request:', error.message);
  console.error('Details:', error);
});

// Write the payload and send the request
req.write(payload);
req.end();
